package school.magiccodex.paper;
import static org.junit.jupiter.api.Assertions.*;import java.util.*;import org.junit.jupiter.api.Test;import school.magiccodex.protocol.ShopAdminProtocol;import school.magiccodex.protocol.ShopAdminProtocol.*;
class ShopAdminProtocolTest {
 Request request(int action,String price){return new Request(action,1,42,"a",2,UUID.randomUUID().toString(),"상품",price,"off","검색",0,"광물",10,-1,"");}
 @Test void mutationRoundTripAndDisabledPrice(){var r=request(ShopAdminProtocol.EDIT,"123.456789");assertEquals(r,ShopAdminProtocol.request(ShopAdminProtocol.encode(r)));assertDoesNotThrow(()->ShopAdminProtocol.price("off"));assertDoesNotThrow(()->ShopAdminProtocol.price("0"));}
 @Test void rejectsPricesAndNamesBeforeHandler(){for(String p:List.of("-1","NaN","1e3","1000000000001","0.1234567",""))assertThrows(IllegalArgumentException.class,()->ShopAdminProtocol.request(ShopAdminProtocol.encode(request(ShopAdminProtocol.ADD,p))));var r=request(ShopAdminProtocol.EDIT,"1");assertThrows(IllegalArgumentException.class,()->ShopAdminProtocol.request(ShopAdminProtocol.encode(new Request(r.action(),1,42,"a",2,r.product(),"","\u0031","off","",0,"",0,-1,""))));}
 @Test void rejectsWrongSessionBadActionAndTrailingBytes(){var r=request(ShopAdminProtocol.LIST,"off");byte[] good=ShopAdminProtocol.encode(r);assertThrows(IllegalArgumentException.class,()->ShopAdminProtocol.request(Arrays.copyOf(good,good.length+1)));assertThrows(IllegalArgumentException.class,()->ShopAdminProtocol.request(ShopAdminProtocol.encode(new Request(99,1,42,"a",2,"","","off","off","",0,"",0,-1,""))));assertThrows(IllegalArgumentException.class,()->ShopAdminProtocol.request(ShopAdminProtocol.encode(new Request(0,1,0,"a",2,"","","off","off","",0,"",0,-1,""))));}
 @Test void inventorySlotCategoryAndSortRoundTripAndBounds(){var r=new Request(ShopAdminProtocol.ADD,1,42,"a",2,"","다이아몬드","2000","400","",0,"광물",160,35,"minecraft:diamond");assertEquals(r,ShopAdminProtocol.request(ShopAdminProtocol.encode(r)));
  for(var bad:List.of(new Request(ShopAdminProtocol.ADD,1,42,"a",2,"","x","1","off","",0,"",0,36,"minecraft:stone"),new Request(ShopAdminProtocol.ADD,1,42,"a",2,"","x","1","off","",0,"",100000,0,"minecraft:stone"),new Request(ShopAdminProtocol.ADD,1,42,"a",2,"","x","1","off","",0,"",-1,0,"minecraft:stone"),new Request(ShopAdminProtocol.ADD,1,42,"a",2,"","x","1","off","",0,"a\nb",0,0,"minecraft:stone")))assertThrows(IllegalArgumentException.class,()->ShopAdminProtocol.request(ShopAdminProtocol.encode(bad)));}
 @Test void fullPreviewAndPaginationRoundTrip(){byte[] b=new byte[32768];Arrays.fill(b,(byte)9);var response=new Response(1,42,"a",2,"",List.of(new Shop("a","상점")),List.of(new Product(UUID.randomUUID().toString(),"커스텀","0","","광물",10,b)),5,6);var actual=ShopAdminProtocol.response(ShopAdminProtocol.encode(response));assertArrayEquals(b,actual.products().getFirst().preview());assertEquals(6,actual.nextOffset());assertEquals("상점",actual.shops().getFirst().title());assertEquals("광물",actual.products().getFirst().category());assertEquals(10,actual.products().getFirst().sort());}
 @Test void malformedPreviewAndOversizedPacketsRejected(){var response=new Response(1,42,"a",2,"",List.of(),List.of(new Product(UUID.randomUUID().toString(),"상품","0","","",0,new byte[32769])),0,-1);assertThrows(IllegalArgumentException.class,()->ShopAdminProtocol.response(ShopAdminProtocol.encode(response)));assertThrows(IllegalArgumentException.class,()->ShopAdminProtocol.request(new byte[60001]));}
}
